og || !$this->_checkoutSession ? null : $this->_checkoutSession->getQuote(); $this->setShortcutHtmlId( $this->_mathRandom->getUniqueHash('ec_shortcut_') )->setCheckoutUrl( $this->getUrl($this->_startAction) ); if ($isInCatalog || null === $quote) { $this->setImageUrl($this->config->getExpressCheckoutShortcutImageUrl($this->_localeResolver->getLocale())); } else { $parameters = ['params' => ['quote' => $quote, 'config' => $this->config]]; $checkoutModel = $this->_checkoutFactory->create($this->_checkoutType, $parameters); $this->setImageUrl($checkoutModel->getCheckoutShortcutImageUrl()); } return $result; } protected function _toHtml() { if (!$this->shouldRender()) { return ''; } return parent::_toHtml(); } protected function shouldRender() { $this->config->setMethod(Config::METHOD_EXPRESS); $isInCatalog = $this->getIsInCatalogProduct(); $isInContext = (bool)(int) $this->config->getValue('in_context'); $isEnabled = ($isInContext && $isInCatalog) || !$isInContext; $this->config->setMethod($this->_paymentMethodCode); return $isEnabled && $this->_shouldRender; } public function isOrPositionBefore() { return $this->getShowOrPosition() == CatalogBlock\ShortcutButtons::POSITION_BEFORE; } public function isOrPositionAfter() { return $this->getShowOrPosition() == CatalogBlock\ShortcutButtons::POSITION_AFTER; } public function getAlias() { return $this->_alias; } } 